def decide(observation, tools):
    direct = tools.direct()
    point = tools.point()
    if point[1] is not None:
        x, y = point[1]
        h = observation['views'][1]['heading']
        r = observation['views'][1]['right_of_end_m']
        d = 1.0 if h == 90 else -1.0
        dx = r + d * (y * 24 - 12)
        return 1, 'right' if dx > 0 else 'left', {}
    if direct[1] > direct[0]:
        return 1, 'right', {}
    return 0, 'left', {}

